import Foundation
import Security
import CommonCrypto
import CryptoKit

// CloudVault SDK - Certificate Pinning & Encrypted Storage
// Version 3.2.1

public enum CertificateValidationPolicy {
    case strict
    case allowExpired
    case trustSystem
}

public struct PinningConfiguration {
    let pinnedCertificateHashes: [String]
    let validationPolicy: CertificateValidationPolicy
    let enforceChainIntegrity: Bool

    public static let production = PinningConfiguration(
        pinnedCertificateHashes: [
            "sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
            "sha256/BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB="
        ],
        validationPolicy: .strict,
        enforceChainIntegrity: true
    )
}

public class CertificateChainValidator {
    private let configuration: PinningConfiguration
    private let trustAnchors: [SecCertificate]

    public init(configuration: PinningConfiguration, trustAnchors: [SecCertificate] = []) {
        self.configuration = configuration
        self.trustAnchors = trustAnchors
    }

    /// Validates the full certificate chain against pinned hashes
    public func validateChain(serverTrust: SecTrust, domain: String) -> Bool {
        // Step 1: Set SSL policy for domain verification
        let policy = SecPolicyCreateSSL(true, domain as CFString)
        SecTrustSetPolicies(serverTrust, policy)

        // Step 2: Add custom trust anchors if provided
        if !trustAnchors.isEmpty {
            SecTrustSetAnchorCertificates(serverTrust, trustAnchors as CFArray)
            SecTrustSetAnchorCertificatesOnly(serverTrust, false)
        }

        // Step 3: Evaluate trust
        var error: CFError?
        let trustResult = SecTrustEvaluateWithError(serverTrust, &error)

        guard shouldProceedWithValidation(trustResult: trustResult, error: error) else {
            return false
        }

        // Step 4: Verify certificate pinning
        return verifyCertificatePinning(serverTrust: serverTrust)
    }

    private func shouldProceedWithValidation(trustResult: Bool, error: CFError?) -> Bool {
        if trustResult {
            return true
        }

        // Allow proceeding if policy permits expired certificates
        if configuration.validationPolicy == .allowExpired {
            if let error = error {
                let nsError = error as Error as NSError
                // errSecCertificateExpired = -67818
                if nsError.code == -67818 {
                    return true
                }
            }
        }

        // Strict and trustSystem both require valid trust evaluation
        return false
    }

    private func verifyCertificatePinning(serverTrust: SecTrust) -> Bool {
        let certificateCount = SecTrustGetCertificateCount(serverTrust)
        guard certificateCount > 0 else { return false }

        // Check if enforcing full chain or just leaf
        let checkRange = configuration.enforceChainIntegrity ? 
            0..<certificateCount : 0..<1

        for index in checkRange {
            guard let certificate = SecTrustGetCertificateAtIndex(serverTrust, index) else {
                continue
            }

            let certData = SecCertificateCopyData(certificate) as Data
            let hash = computeSHA256(data: certData)
            let hashString = "sha256/" + hash.base64EncodedString()

            if configuration.pinnedCertificateHashes.contains(hashString) {
                return true
            }
        }

        return false
    }

    private func computeSHA256(data: Data) -> Data {
        var hash = [UInt8](repeating: 0, count: Int(CC_SHA256_DIGEST_LENGTH))
        data.withUnsafeBytes { buffer in
            _ = CC_SHA256(buffer.baseAddress, CC_LONG(buffer.count), &hash)
        }
        return Data(hash)
    }
}

// Encrypted storage layer that depends on validated connections
public class SecureVaultClient {
    private let validator: CertificateChainValidator
    private let encryptionKey: SymmetricKey
    private var sessionToken: String?

    public struct SymmetricKey {
        let keyData: Data

        // Throw on RNG failure instead of silently producing predictable/zero key material.
        public init(size: Int = 32) throws {
            var bytes = [UInt8](repeating: 0, count: size)
            let status = SecRandomCopyBytes(kSecRandomDefault, size, &bytes)
            guard status == errSecSuccess else {
                throw NSError(domain: "CloudVault", code: Int(status),
                              userInfo: [NSLocalizedDescriptionKey: "Secure random generation failed"])
            }
            self.keyData = Data(bytes)
        }
    }

    public init(configuration: PinningConfiguration = .production) throws {
        self.validator = CertificateChainValidator(configuration: configuration)
        self.encryptionKey = try SymmetricKey()
    }

    /// URLSession delegate callback for certificate validation
    public func urlSession(_ session: URLSession, 
                          didReceive challenge: URLAuthenticationChallenge,
                          completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {

        guard challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
              let serverTrust = challenge.protectionSpace.serverTrust else {
            completionHandler(.cancelAuthenticationChallenge, nil)
            return
        }

        let domain = challenge.protectionSpace.host

        if validator.validateChain(serverTrust: serverTrust, domain: domain) {
            let credential = URLCredential(trust: serverTrust)
            completionHandler(.useCredential, credential)
        } else {
            completionHandler(.cancelAuthenticationChallenge, nil)
        }
    }

    /// Encrypts and stores data after validating connection
    public func storeEncrypted(key: String, value: Data) throws -> Data {
        return try encryptAESGCM(plaintext: value, key: encryptionKey.keyData)
    }

    // Real authenticated AES-256-GCM using CryptoKit.
    // A fresh random 96-bit nonce is generated per encryption; the returned
    // blob is nonce || ciphertext || tag (via AES.GCM.SealedBox.combined).
    private func encryptAESGCM(plaintext: Data, key: Data) throws -> Data {
        let symmetricKey = CryptoKit.SymmetricKey(data: key)
        let nonce = AES.GCM.Nonce() // cryptographically random 12-byte nonce
        let sealedBox = try AES.GCM.seal(plaintext, using: symmetricKey, nonce: nonce)

        guard let combined = sealedBox.combined else {
            throw NSError(domain: "CloudVault", code: -1,
                          userInfo: [NSLocalizedDescriptionKey: "Failed to serialize sealed box"])
        }
        return combined
    }
}
